-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.enchant_shot(p_world uuid, p_uid uuid, p_id integer, p_bow item)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare e record; c creature;
begin
  if p_bow.id is null or p_bow.enchant is null then return; end if;
  select * into e from enchantments() x where x.id = p_bow.enchant->>'id' and x.effect in ('flame', 'frost');
  if e.id is null then return; end if;
  select * into c from creature where world_id = p_world and id = p_id;
  if c.id is null or c.health <= 0 then return; end if;
  if random() >= enchant_hit_chance(e.id, (p_bow.enchant->>'ql')::double precision) then return; end if;
  if e.effect = 'flame' then perform class_burn(p_world, p_uid, p_id, enchant_burn_each(), enchant_burn_secs());
  else perform enchant_frost(p_world, p_id); end if;
  perform tell(p_world, p_uid, e.name || ': '
    || replace(enchant_hit_said(e.effect), '{t}', lower((select s.name from species_def s where s.id = c.species))), 'fight');
end $function$
